package eit_image_availability_coordinator.EIT_Image_Availability_Coordinator

import org.sireum._
import art.Art
import eit_image_availability_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait ArtifactLifecycle_coordination_artifact_lifecycle_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITImageAvailabilitySystem_Instance_coordination_artifact_lifecycle)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITImageAvailabilitySystem_Instance_coordination_artifact_lifecycle)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITImageAvailabilitySystem_Instance_coordination_artifact_lifecycle)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITImageAvailabilitySystem_Instance_coordination_artifact_lifecycle)
  }

  /** helper function to set the values of all input ports.
   * @param imageFacts payload for data port imageFacts
   * @param recoveryFrame payload for data port recoveryFrame
   * @param admissionFrame payload for data port admissionFrame
   * @param reviewFacts payload for data port reviewFacts
   */
  def put_concrete_inputs(imageFacts : EIT_Image_Availability_Coordinator.ImageFacts.Type,
                          recoveryFrame : EIT_Image_Availability_Coordinator.RecoveryFrame,
                          admissionFrame : EIT_Image_Availability_Coordinator.AdmissionFrame,
                          reviewFacts : EIT_Image_Availability_Coordinator.ReviewFacts.Type): Unit = {
    put_imageFacts(imageFacts)
    put_recoveryFrame(recoveryFrame)
    put_admissionFrame(admissionFrame)
    put_reviewFacts(reviewFacts)
  }


  /** helper function to check ArtifactLifecycle_coordination_artifact_lifecycle's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param artifactFrame method that will be called with the value of the outgoing data
   *        port 'artifactFrame'.
   */
  def check_concrete_output(artifactFrame: EIT_Image_Availability_Coordinator.ArtifactFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val artifactFrameValue: EIT_Image_Availability_Coordinator.ArtifactFrame = get_artifactFrame().get
    if(!artifactFrame(artifactFrameValue)) {
      testFailures = testFailures :+ st"'artifactFrame' did not match expected: value of the outgoing data port is ${artifactFrameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_imageFacts(value : EIT_Image_Availability_Coordinator.ImageFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_artifact_lifecycle.operational_api.imageFacts_Id, EIT_Image_Availability_Coordinator.ImageFacts_Payload(value))
  }

  // setter for in DataPort
  def put_recoveryFrame(value : EIT_Image_Availability_Coordinator.RecoveryFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_artifact_lifecycle.operational_api.recoveryFrame_Id, EIT_Image_Availability_Coordinator.RecoveryFrame_Payload(value))
  }

  // setter for in DataPort
  def put_admissionFrame(value : EIT_Image_Availability_Coordinator.AdmissionFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_artifact_lifecycle.operational_api.admissionFrame_Id, EIT_Image_Availability_Coordinator.AdmissionFrame_Payload(value))
  }

  // setter for in DataPort
  def put_reviewFacts(value : EIT_Image_Availability_Coordinator.ReviewFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_artifact_lifecycle.operational_api.reviewFacts_Id, EIT_Image_Availability_Coordinator.ReviewFacts_Payload(value))
  }

  // getter for out DataPort
  def get_artifactFrame(): Option[EIT_Image_Availability_Coordinator.ArtifactFrame] = {
    val value: Option[EIT_Image_Availability_Coordinator.ArtifactFrame] = get_artifactFrame_payload() match {
      case Some(EIT_Image_Availability_Coordinator.ArtifactFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port artifactFrame.  Expecting 'EIT_Image_Availability_Coordinator.ArtifactFrame_Payload' but received ${v}")
      case _ => None[EIT_Image_Availability_Coordinator.ArtifactFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_artifactFrame_payload(): Option[EIT_Image_Availability_Coordinator.ArtifactFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_artifact_lifecycle.initialization_api.artifactFrame_Id).asInstanceOf[Option[EIT_Image_Availability_Coordinator.ArtifactFrame_Payload]]
  }

}
